SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS objetos_equipo (
    slug VARCHAR(120) NOT NULL,
    nombre VARCHAR(180) NOT NULL,
    categoria VARCHAR(120) NOT NULL,
    coste VARCHAR(100) NOT NULL,
    peso VARCHAR(100) NULL,
    dano VARCHAR(180) NULL,
    clase_armadura VARCHAR(180) NULL,
    propiedades TEXT NULL,
    descripcion LONGTEXT NULL,
    PRIMARY KEY (slug),
    KEY idx_objetos_equipo_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS objetos_magicos (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug VARCHAR(180) NOT NULL,
    nombre VARCHAR(180) NOT NULL,
    rareza VARCHAR(30) NOT NULL,
    tipo VARCHAR(100) NOT NULL,
    sintonizacion VARCHAR(30) NOT NULL,
    fuente VARCHAR(50) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_objetos_magicos_slug (slug),
    KEY idx_objetos_magicos_rareza_nombre (rareza, nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE nombre = VALUES(nombre), categoria = VALUES(categoria), coste = VALUES(coste), peso = VALUES(peso), dano = VALUES(dano), clase_armadura = VALUES(clase_armadura), propiedades = VALUES(propiedades), descripcion = VALUES(descripcion);
