INSERT INTO objetos_equipo (slug, nombre, categoria, coste, peso, dano, clase_armadura, propiedades, descripcion) VALUES
('abacus', 'Abacus', 'Adventuring Gear', '2 gp', '2 lb', NULL, NULL, NULL, NULL),
('acid-vial', 'Acid (vial)', 'Adventuring Gear', '25 gp', '1 lb', NULL, NULL, NULL, 'As an action, you can splash the contents of this vial onto a creature within 5 feet of you or throw the vial up to 20 feet, shattering it on impact. In either case, make a ranged attack against a creature or object, treating the acid as an improvised weapon.\nOn a hit, the target takes 2d6 acid damage.'),
('alchemists-fire-flask', 'Alchemist''s fire (flask)', 'Adventuring Gear', '50 gp', '1 lb', NULL, NULL, NULL, 'This sticky, adhesive fluid ignites when exposed to air.\nAs an action, you can throw this flask up to 20 feet, shattering it on impact. Make a ranged attack against a creature or object, treating the alchemist''s fire as an improvised weapon.\nOn a hit, the target takes 1d4 fire damage at the start of each of its turns. A creature can end this damage by using its action to make a DC 10 Dexterity check to extinguish the flames.'),
('alchemists-supplies', 'Alchemist''s Supplies', 'Tools', '50 gp', '8 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('alms-box', 'Alms box', 'Adventuring Gear', '0 cp', '0 lb', NULL, NULL, NULL, 'A small box for alms, typically found in a priest''s pack.'),
('amulet', 'Amulet', 'Adventuring Gear', '5 gp', '1 lb', NULL, NULL, NULL, 'A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic.\nAppendix B lists the symbols commonly associated with many gods in the multiverse. A cleric or paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield.'),
('animal-feed-1-day', 'Animal Feed (1 day)', 'Mounts and Vehicles', '5 cp', '10 lb', NULL, NULL, NULL, NULL),
('antitoxin-vial', 'Antitoxin (vial)', 'Adventuring Gear', '50 gp', '0 lb', NULL, NULL, NULL, 'A creature that drinks this vial of liquid gains advantage on saving throws against poison for 1 hour. It confers no benefit to undead or constructs.'),
('arrow', 'Arrow', 'Adventuring Gear', '1 gp', '1 lb', NULL, NULL, NULL, NULL),
('backpack', 'Backpack', 'Adventuring Gear', '2 gp', '5 lb', NULL, NULL, NULL, NULL),
('bagpipes', 'Bagpipes', 'Tools', '30 gp', '6 lb', NULL, NULL, NULL, 'Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.'),
('ball-bearings-bag-of-1000', 'Ball bearings (bag of 1,000)', 'Adventuring Gear', '1 gp', '2 lb', NULL, NULL, NULL, 'As an action, you can spill these tiny metal balls from their pouch to cover a level, square area that is 10 feet on a side.\nA creature moving across the covered area must succeed on a DC 10 Dexterity saving throw or fall prone.\nA creature moving through the area at half speed doesn''t need to make the save.'),
('barding-breastplate', 'Barding: Breastplate', 'Mounts and Vehicles', '1600 gp', '40 lb', NULL, NULL, NULL, 'Barding is armor designed to protect an animal''s head, neck, chest, and body. Any type of armor shown on the Armor table can be purchased as barding. The cost is four times the equivalent armor made for humanoids, and it weighs twice as much.'),
('barding-chain-mail', 'Barding: Chain mail', 'Mounts and Vehicles', '300 gp', '110 lb', NULL, NULL, NULL, 'Barding is armor designed to protect an animal''s head, neck, chest, and body. Any type of armor shown on the Armor table can be purchased as barding. The cost is four times the equivalent armor made for humanoids, and it weighs twice as much.'),
('barding-chain-shirt', 'Barding: Chain shirt', 'Mounts and Vehicles', '200 gp', '40 lb', NULL, NULL, NULL, 'Barding is armor designed to protect an animal''s head, neck, chest, and body. Any type of armor shown on the Armor table can be purchased as barding. The cost is four times the equivalent armor made for humanoids, and it weighs twice as much.'),
