('case-crossbow-bolt', 'Case, crossbow bolt', 'Adventuring Gear', '1 gp', '1 lb', NULL, NULL, NULL, 'This wooden case can hold up to twenty crossbow bolts.'),
('case-map-or-scroll', 'Case, map or scroll', 'Adventuring Gear', '1 gp', '1 lb', NULL, NULL, NULL, 'This cylindrical leather case can hold up to ten rolled-up sheets of paper or five rolled-up sheets of parchment.'),
