('chest', 'Chest', 'Adventuring Gear', '5 gp', '25 lb', NULL, NULL, NULL, NULL),
('climbers-kit', 'Climber''s Kit', 'Adventuring Gear', '25 gp', '12 lb', NULL, NULL, NULL, 'A climber''s kit includes special pitons, boot tips, gloves, and a harness. You can use the climber''s kit as an action to anchor yourself; when you do, you can''t fall more than 25 feet from the point where you anchored yourself, and you can''t climb more than 25 feet away from that point without undoing the anchor.'),
('clothes-common', 'Clothes, common', 'Adventuring Gear', '5 sp', '3 lb', NULL, NULL, NULL, NULL),
('clothes-costume', 'Clothes, costume', 'Adventuring Gear', '5 gp', '4 lb', NULL, NULL, NULL, NULL),
