INSERT INTO objetos_equipo (slug, nombre, categoria, coste, peso, dano, clase_armadura, propiedades, descripcion) VALUES
('hammer-sledge', 'Hammer, sledge', 'Adventuring Gear', '2 gp', '10 lb', NULL, NULL, NULL, NULL),
('hammer', 'Hammer', 'Adventuring Gear', '1 gp', '3 lb', NULL, NULL, NULL, NULL),
('handaxe', 'Handaxe', 'Weapon', '5 gp', '2 lb', '1d6 (Slashing)\nPropiedades:\nLight\nThrown\nMonk', NULL, 'Light\nThrown\nMonk', NULL),
('healers-kit', 'Healer''s Kit', 'Adventuring Gear', '5 gp', '3 lb', NULL, NULL, NULL, 'This kit is a leather pouch containing bandages, salves, and splints. The kit has ten uses. As an action, you can expend one use of the kit to stabilize a creature that has 0 hit points, without needing to make a Wisdom (Medicine) check.'),
('herbalism-kit', 'Herbalism Kit', 'Adventuring Gear', '5 gp', '3 lb', NULL, NULL, NULL, 'This kit contains a variety of instruments such as clippers, mortar and pestle, and pouches and vials used by herbalists to create remedies and potions. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to identify or apply herbs. Also, proficiency with this kit is required to create antitoxin and potions of healing.'),
('hide-armor', 'Hide Armor', 'Armor', '10 gp', '12 lb', NULL, 'Base: 12 + Mod. Destreza', NULL, NULL),
('holy-water-flask', 'Holy water (flask)', 'Adventuring Gear', '25 gp', '1 lb', NULL, NULL, NULL, 'As an action, you can splash the contents of this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. In either case, make a ranged attack against a target creature, treating the holy water as an improvised weapon.\nIf the target is a fiend or undead, it takes 2d6 radiant damage.\nA cleric or paladin may create holy water by performing a special ritual.\nThe ritual takes 1 hour to perform, uses 25 gp worth of powdered silver, and requires the caster to expend a 1st-level spell slot.'),
('horn', 'Horn', 'Tools', '3 gp', '2 lb', NULL, NULL, NULL, 'Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.'),
('horse-draft', 'Horse, draft', 'Mounts and Vehicles', '50 gp', NULL, NULL, NULL, NULL, NULL),
('horse-riding', 'Horse, riding', 'Mounts and Vehicles', '75 gp', NULL, NULL, NULL, NULL, NULL),
('hourglass', 'Hourglass', 'Adventuring Gear', '25 gp', '1 lb', NULL, NULL, NULL, NULL),
('hunting-trap', 'Hunting trap', 'Adventuring Gear', '5 gp', '25 lb', NULL, NULL, NULL, 'When you use your action to set it, this trap forms a saw-toothed steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground.\nA creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 piercing damage and stop moving. Thereafter, until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet long).\nA creature can use its action to make a DC 13 Strength check, freeing itself or another creature within its reach on a success. Each failed check deals 1 piercing damage to the trapped creature.'),
('ink-1-ounce-bottle', 'Ink (1 ounce bottle)', 'Adventuring Gear', '10 gp', '0 lb', NULL, NULL, NULL, NULL),
('ink-pen', 'Ink pen', 'Adventuring Gear', '2 cp', '0 lb', NULL, NULL, NULL, NULL),
('javelin', 'Javelin', 'Weapon', '5 sp', '2 lb', '1d6 (Piercing)\nPropiedades:\nThrown\nMonk', NULL, 'Thrown\nMonk', NULL),
('jewelers-tools', 'Jeweler''s Tools', 'Tools', '25 gp', '2 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('jug-or-pitcher', 'Jug or pitcher', 'Adventuring Gear', '2 cp', '4 lb', NULL, NULL, NULL, NULL),
('keelboat', 'Keelboat', 'Mounts and Vehicles', '3000 gp', NULL, NULL, NULL, NULL, 'Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land.'),
('ladder-10-foot', 'Ladder (10-foot)', 'Adventuring Gear', '1 sp', '25 lb', NULL, NULL, NULL, NULL),
('lamp', 'Lamp', 'Adventuring Gear', '5 sp', '1 lb', NULL, NULL, NULL, 'A lamp casts bright light in a 15-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.'),
('lance', 'Lance', 'Weapon', '10 gp', '6 lb', '1d12 (Piercing)\nPropiedades:\nReach\nSpecial', NULL, 'Reach\nSpecial', NULL),
('lantern-bullseye', 'Lantern, bullseye', 'Adventuring Gear', '10 gp', '2 lb', NULL, NULL, NULL, 'A bullseye lantern casts bright light in a 60-foot cone and dim light for an additional 60 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.'),
('lantern-hooded', 'Lantern, hooded', 'Adventuring Gear', '5 gp', '2 lb', NULL, NULL, NULL, 'A hooded lantern casts bright light in a 30-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil. As an action, you can lower the hood, reducing the light to dim light in a 5-foot radius.'),
('leather-armor', 'Leather Armor', 'Armor', '10 gp', '10 lb', NULL, 'Base: 11 + Mod. Destreza', NULL, NULL),
('leatherworkers-tools', 'Leatherworker''s Tools', 'Tools', '5 gp', '5 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('light-hammer', 'Light hammer', 'Weapon', '2 gp', '2 lb', '1d4 (Bludgeoning)\nPropiedades:\nLight\nThrown\nMonk', NULL, 'Light\nThrown\nMonk', NULL),
('little-bag-of-sand', 'Little bag of sand', 'Adventuring Gear', '0 cp', '0 lb', NULL, NULL, NULL, 'A small bag of sand, typically found in a scholar''s pack.'),
('lock', 'Lock', 'Adventuring Gear', '10 gp', '1 lb', NULL, NULL, NULL, 'A key is provided with the lock. Without the key, a creature proficient with thieves'' tools can pick this lock with a successful DC 15 Dexterity check. Your GM may decide that better locks are available for higher prices.'),
('longbow', 'Longbow', 'Weapon', '50 gp', '2 lb', '1d8 (Piercing)\nPropiedades:\nAmmunition\nHeavy\nTwo-Handed', NULL, 'Ammunition\nHeavy\nTwo-Handed', NULL),
('longship', 'Longship', 'Mounts and Vehicles', '10000 gp', NULL, NULL, NULL, NULL, NULL),
('longsword', 'Longsword', 'Weapon', '15 gp', '3 lb', '1d8 (Slashing)\nPropiedades:\nVersatile', NULL, 'Versatile', NULL),
('lute', 'Lute', 'Tools', '35 gp', '2 lb', NULL, NULL, NULL, 'Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.'),
('lyre', 'Lyre', 'Tools', '30 gp', '2 lb', NULL, NULL, NULL, 'Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.'),
('mace', 'Mace', 'Weapon', '5 gp', '4 lb', '1d6 (Bludgeoning)\nPropiedades:\nMonk', NULL, 'Monk', NULL),
('magnifying-glass', 'Magnifying glass', 'Adventuring Gear', '100 gp', '0 lb', NULL, NULL, NULL, 'This lens allows a closer look at small objects. It is also useful as a substitute for flint and steel when starting fires. Lighting a fire with a magnifying glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite.\nA magnifying glass grants advantage on any ability check made to appraise or inspect an item that is small or highly detailed.'),
('manacles', 'Manacles', 'Adventuring Gear', '2 gp', '6 lb', NULL, NULL, NULL, 'These metal restraints can bind a Small or Medium creature. Escaping the manacles requires a successful DC 20 Dexterity check. Breaking them requires a successful DC 20 Strength check.\nEach set of manacles comes with one key. Without the key, a creature proficient with thieves'' tools can pick the manacles'' lock with a successful DC 15 Dexterity check. Manacles have 15 hit points.'),
('masons-tools', 'Mason''s Tools', 'Tools', '10 gp', '8 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('mastiff', 'Mastiff', 'Mounts and Vehicles', '25 gp', NULL, NULL, NULL, NULL, NULL),
('maul', 'Maul', 'Weapon', '10 gp', '10 lb', '2d6 (Bludgeoning)\nPropiedades:\nHeavy\nTwo-Handed', NULL, 'Heavy\nTwo-Handed', NULL),
('mess-kit', 'Mess Kit', 'Adventuring Gear', '2 sp', '1 lb', NULL, NULL, NULL, 'This tin box contains a cup and simple cutlery. The box clamps together, and one side can be used as a cooking pan and the other as a plate or shallow bowl.'),
('mirror-steel', 'Mirror, steel', 'Adventuring Gear', '5 gp', '0.5 lb', NULL, NULL, NULL, NULL),
('morningstar', 'Morningstar', 'Weapon', '15 gp', '4 lb', '1d8 (Piercing)', NULL, NULL, NULL),
('mule', 'Mule', 'Mounts and Vehicles', '8 gp', NULL, NULL, NULL, NULL, NULL),
('navigators-tools', 'Navigator''s Tools', 'Tools', '25 gp', '2 lb', NULL, NULL, NULL, 'This set of instruments is used for navigation at sea. Proficiency with navigator''s tools lets you chart a ship''s course and follow navigation charts. In addition, these tools allow you to add your proficiency bonus to any ability check you make to avoid getting lost at sea.'),
('net', 'Net', 'Weapon', '1 gp', '3 lb', NULL, NULL, NULL, NULL),
('oil-flask', 'Oil (flask)', 'Adventuring Gear', '1 sp', '1 lb', NULL, NULL, NULL, 'Oil usually comes in a clay flask that holds 1 pint.\nAs an action, you can splash the oil in this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. Make a ranged attack against a target creature or object, treating the oil as an improvised weapon.\nOn a hit, the target is covered in oil. If the target takes any fire damage before the oil dries (after 1 minute), the target takes an additional 5 fire damage from the burning oil.\nYou can also pour a flask of oil on the ground to cover a 5-foot-square area, provided that the surface is level.\nIf lit, the oil burns for 2 rounds and deals 5 fire damage to any creature that enters the area or ends its turn in the area. A creature can take this damage only once per turn.'),
('orb', 'Orb', 'Adventuring Gear', '20 gp', '3 lb', NULL, NULL, NULL, 'An arcane focus is a special item--an orb, a crystal, a rod, a specially constructed staff, a wand-like length of wood, or some similar item--designed to channel the power of arcane spells. A sorcerer, warlock, or wizard can use such an item as a spellcasting focus.'),
('padded-armor', 'Padded Armor', 'Armor', '5 gp', '8 lb', NULL, 'Base: 11 + Mod. Destreza', NULL, NULL),
('painters-supplies', 'Painter''s Supplies', 'Tools', '10 gp', '5 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('pan-flute', 'Pan flute', 'Tools', '12 gp', '2 lb', NULL, NULL, NULL, 'Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency.'),
('paper-one-sheet', 'Paper (one sheet)', 'Adventuring Gear', '2 sp', '0 lb', NULL, NULL, NULL, NULL),
('parchment-one-sheet', 'Parchment (one sheet)', 'Adventuring Gear', '1 sp', '0 lb', NULL, NULL, NULL, NULL),
('perfume-vial', 'Perfume (vial)', 'Adventuring Gear', '5 gp', '0 lb', NULL, NULL, NULL, NULL),
('pick-miners', 'Pick, miner''s', 'Adventuring Gear', '2 gp', '10 lb', NULL, NULL, NULL, NULL),
('pike', 'Pike', 'Weapon', '5 gp', '18 lb', '1d10 (Piercing)\nPropiedades:\nHeavy\nReach\nTwo-Handed', NULL, 'Heavy\nReach\nTwo-Handed', NULL),
('piton', 'Piton', 'Adventuring Gear', '5 cp', '0.25 lb', NULL, NULL, NULL, NULL),
('plate-armor', 'Plate Armor', 'Armor', '1500 gp', '65 lb', NULL, 'Base: 18', NULL, NULL),
('playing-card-set', 'Playing Card Set', 'Tools', '5 sp', '0 lb', NULL, NULL, NULL, 'This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-Dragon Ante). A few common examples appear on the Tools table, but other kinds of gaming sets exist. If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set. Each type of gaming set requires a separate proficiency.'),
('poison-basic-vial', 'Poison, basic (vial)', 'Adventuring Gear', '100 gp', '0 lb', NULL, NULL, NULL, 'You can use the poison in this vial to coat one slashing or piercing weapon or up to three pieces of ammunition. Applying the poison takes an action. A creature hit by the poisoned weapon or ammunition must make a DC 10 Constitution saving throw or take 1d4 poison damage. Once applied, the poison retains potency for 1 minute before drying.'),
('poisoners-kit', 'Poisoner''s Kit', 'Adventuring Gear', '50 gp', '2 lb', NULL, NULL, NULL, 'A poisoner''s kit includes the vials, chemicals, and other equipment necessary for the creation of poisons. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to craft or use poisons.'),
('pole-10-foot', 'Pole (10-foot)', 'Adventuring Gear', '5 cp', '7 lb', NULL, NULL, NULL, NULL),
('pony', 'Pony', 'Mounts and Vehicles', '30 gp', NULL, NULL, NULL, NULL, NULL),
('pot-iron', 'Pot, iron', 'Adventuring Gear', '2 gp', '10 lb', NULL, NULL, NULL, NULL),
('potters-tools', 'Potter''s Tools', 'Tools', '10 gp', '3 lb', NULL, NULL, NULL, 'These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency.'),
('pouch', 'Pouch', 'Adventuring Gear', '5 sp', '1 lb', NULL, NULL, NULL, 'A cloth or leather pouch can hold up to 20 sling bullets or 50 blowgun needles, among other things. A compartmentalized pouch for holding spell components is called a component pouch (described earlier in this section).'),
('priests-pack', 'Priest''s Pack', 'Adventuring Gear', '19 gp', NULL, NULL, NULL, NULL, NULL),
('quarterstaff', 'Quarterstaff', 'Weapon', '2 sp', '4 lb', '1d6 (Bludgeoning)\nPropiedades:\nVersatile\nMonk', NULL, 'Versatile\nMonk', NULL),
('quiver', 'Quiver', 'Adventuring Gear', '1 gp', '1 lb', NULL, NULL, NULL, 'A quiver can hold up to 20 arrows.'),
('ram-portable', 'Ram, portable', 'Adventuring Gear', '4 gp', '35 lb', NULL, NULL, NULL, 'You can use a portable ram to break down doors. When doing so, you gain a +4 bonus on the Strength check. One other character can help you use the ram, giving you advantage on this check.'),
('rapier', 'Rapier', 'Weapon', '25 gp', '2 lb', '1d8 (Piercing)\nPropiedades:\nFinesse', NULL, 'Finesse', NULL),
('rations-1-day', 'Rations (1 day)', 'Adventuring Gear', '5 sp', '2 lb', NULL, NULL, NULL, 'Rations consist of dry foods suitable for extended travel, including jerky, dried fruit, hardtack, and nuts.'),
('reliquary', 'Reliquary', 'Adventuring Gear', '5 gp', '2 lb', NULL, NULL, NULL, 'A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic.\nAppendix B lists the symbols commonly associated with many gods in the multiverse. A cleric or paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield.'),
('ring-mail', 'Ring Mail', 'Armor', '30 gp', '40 lb', NULL, 'Base: 14', NULL, NULL),
('robes', 'Robes', 'Adventuring Gear', '1 gp', '4 lb', NULL, NULL, NULL, NULL),
('rod', 'Rod', 'Adventuring Gear', '10 gp', '2 lb', NULL, NULL, NULL, 'An arcane focus is a special item--an orb, a crystal, a rod, a specially constructed staff, a wand-like length of wood, or some similar item--designed to channel the power of arcane spells. A sorcerer, warlock, or wizard can use such an item as a spellcasting focus.'),
('rope-hempen-50-feet', 'Rope, hempen (50 feet)', 'Adventuring Gear', '1 gp', '10 lb', NULL, NULL, NULL, 'Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check.'),
('rope-silk-50-feet', 'Rope, silk (50 feet)', 'Adventuring Gear', '10 gp', '5 lb', NULL, NULL, NULL, 'Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check.'),
('rowboat', 'Rowboat', 'Mounts and Vehicles', '50 gp', NULL, NULL, NULL, NULL, 'Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land.'),
('sack', 'Sack', 'Adventuring Gear', '1 cp', '0.5 lb', NULL, NULL, NULL, NULL),
('saddle-exotic', 'Saddle, Exotic', 'Mounts and Vehicles', '60 gp', '50 lb', NULL, NULL, NULL, 'An exotic saddle is required for riding any aquatic or flying mount.'),
('saddle-military', 'Saddle, Military', 'Mounts and Vehicles', '20 gp', '30 lb', NULL, NULL, NULL, 'A military saddle braces the rider, helping you keep your seat on an active mount in battle. It gives you advantage on any check you make to remain mounted.'),
('saddle-pack', 'Saddle, Pack', 'Mounts and Vehicles', '5 gp', '15 lb', NULL, NULL, NULL, NULL),
('saddle-riding', 'Saddle, Riding', 'Mounts and Vehicles', '10 gp', '25 lb', NULL, NULL, NULL, NULL),
