('scale-mail', 'Scale Mail', 'Armor', '50 gp', '45 lb', NULL, 'Base: 14 + Mod. Destreza', NULL, NULL),
('scale-merchants', 'Scale, merchant''s', 'Adventuring Gear', '5 gp', '3 lb', NULL, NULL, NULL, 'A scale includes a small balance, pans, and a suitable assortment of weights up to 2 pounds. With it, you can measure the exact weight of small objects, such as raw precious metals or trade goods, to help determine their worth.'),
('scholars-pack', 'Scholar''s Pack', 'Adventuring Gear', '40 gp', NULL, NULL, NULL, NULL, NULL),
